    constructor(C _c) { c = _c; }
    function run(uint lockTime, uint amount, uint collectAmt, uint minSum) public payable {
        require(amount > 0);
        require(collectAmt > 0);
        require(address(this).balance >= amount);
        c.SetMinSum(minSum);
        c.Initialized();
        c.Put{value: amount}(lockTime);
        (bool beforeOk, uint balBefore) = tryCollect(collectAmt);
        uint recordedBefore = c.Acc(address(this)).balance;
        uint unlockTime = c.Acc(address(this)).unlockTime;
        // try Collect after the lock expires
        advanceWait(lockTime, unlockTime);
        bool revertedEarly = beforeOk;
        // perform the post-lock collect
        bool revertedLate;
        try c.Collect{value: 0}(collectAmt) { revertedLate = false; } catch { revertedLate = true; }
        uint recordedAfter = c.Acc(address(this)).balance;
        assert(revertedEarly && (!revertedLate ? recordedAfter < recordedBefore : true));
    }
    function tryCollect(uint am) internal returns (bool ok) {
        try c.Collect{value: 0}(am) { ok = false; } catch { ok = true; }
    }
    function advanceWait(uint lockTime, uint unlockTime) internal {
        // if lockTime is 0 the lock already expired; otherwise we cannot wait,
        // so only assert the pre-lock revert; rely on Collect revert flag.
        lockTime; unlockTime;
    }
    receive() external payable {}
}

